;(globalThis.BangbomChat=globalThis.BangbomChat||{}).theme=`
:host{all:initial;color-scheme:light;--ink:#182f2c;--muted:#485e58;--green:#185943;--line:#d9e3db;font:15px/1.55 system-ui,-apple-system,'Apple SD Gothic Neo','Malgun Gothic',sans-serif;color:var(--ink);position:relative;z-index:var(--bb-z,1000)}*,*:before,*:after{box-sizing:border-box}button,input{font:inherit}button{cursor:pointer;color:inherit;-webkit-tap-highlight-color:transparent}button:focus-visible,input:focus-visible,[tabindex]:focus-visible{outline:3px solid #a16b15;outline-offset:2px}button:disabled{opacity:.55;cursor:wait}[hidden]{display:none!important}.fab{position:fixed;right:max(18px,env(safe-area-inset-right));bottom:max(20px,env(safe-area-inset-bottom));border:0;background:var(--green);color:#fff;border-radius:30px;padding:13px 21px;font-weight:750;box-shadow:0 6px 22px #16342635}.panel{position:fixed;right:18px;bottom:max(18px,env(safe-area-inset-bottom));width:min(418px,calc(100vw - 36px));height:min(720px,calc(100dvh - 36px));display:flex;flex-direction:column;background:#f8faf6;box-shadow:0 12px 60px #18372a36;border:1px solid #bfcec3;border-radius:22px;overflow:hidden;isolation:isolate}.panel header{display:flex;align-items:center;gap:10px;background:#153e33;color:#fff;padding:17px 16px;flex:none}.mark{width:37px;height:37px;display:grid;place-items:center;background:#dff2b7;border-radius:11px;color:#194a37;font-size:19px;font-weight:900}.sub{font-size:10px;line-height:1.4;letter-spacing:.14em;color:#def2cd;font-weight:700}.title{font-size:18px;font-weight:750;letter-spacing:-.04em;line-height:1.5}.headspace{flex:1}.icon{color:white;background:transparent;border:1px solid #729186;border-radius:8px;padding:4px 9px;min-height:34px;font-size:12px}.close{font-size:18px;line-height:1.2}.bar{background:white;border-bottom:1px solid var(--line);padding:10px 15px;flex:none}.bar button{border:0;background:none;color:var(--green);font-weight:700;font-size:12px;text-align:left;padding:1px;line-height:1.5}.log{flex:1;min-height:0;overflow:auto;padding:17px 14px;overscroll-behavior:contain;scrollbar-width:thin}.who,.eyebrow{font-size:10px;letter-spacing:.12em;font-weight:800;color:var(--green)}.msg{margin:0 0 12px;overflow-wrap:anywhere}.msg.me{text-align:right}.bubble{display:inline-block;margin-top:3px;max-width:95%;background:white;border:1px solid var(--line);border-radius:3px 14px 14px;padding:10px 12px;font-size:14px;text-align:left;white-space:pre-line;word-break:keep-all}.me .bubble{background:#dcecd4;border-color:#c7ddc0;border-radius:14px 3px 14px 14px}.choices{display:flex;gap:6px;flex-wrap:wrap;margin:6px 0 12px}.btn{background:white;border:1px solid #a9bfb1;color:#24553e;font-size:13px;font-weight:650;border-radius:12px;min-height:36px;padding:6px 10px;text-align:left}.btn:hover{background:#eff5e9}.btn.primary{background:#1c533e;color:white;border-color:#1c533e}.btn.primary:hover{background:#113e2d}.card,.pair{background:#fff;border:1px solid var(--line);border-radius:14px;padding:13px;margin:8px 0;overflow-wrap:anywhere}.cardtop{display:flex;justify-content:space-between;gap:8px;align-items:center}.tag{font-size:10px;padding:2px 7px;border:1px solid #bad2be;color:#2a5338;border-radius:15px;background:#f4f9ee}.tag.sample{color:#79491a;background:#fff5e1;border-color:#e9c991}.card h3{font-size:17px;margin:5px 0 2px;letter-spacing:-.04em}.number{font-size:15px;font-weight:750}.small,.source{font-size:12px;color:var(--muted)}.source{font-size:10px}.reason{margin:9px 0;padding:8px 10px;border-left:3px solid #90b87a;background:#f3f7ee;font-size:12px}.card .choices{margin:7px 0 1px}.composer{background:white;border-top:1px solid var(--line);padding:10px 12px max(10px,env(safe-area-inset-bottom));flex:none}.box{display:flex;gap:6px;align-items:center;border:1px solid #acbfb0;background:#f7faf5;border-radius:12px;padding:4px}.box input{min-width:0;flex:1;background:transparent;border:0;padding:6px 7px;font-size:16px;color:var(--ink)}.send{padding:6px 9px;background:var(--green);color:white;border:0;border-radius:8px;font-size:13px;font-weight:700;min-height:34px}.privacy{margin:6px 2px 0;font-size:10px;color:var(--muted)}.pair strong{font-size:14px}.pair p{font-size:13px;margin:4px 0}.sheet{position:absolute;inset:0;display:flex;flex-direction:column;background:#f6f8f3}.sheethead{display:flex;align-items:center;justify-content:space-between;padding:16px;background:#153e33;color:white}.sheethead h2{font-size:18px;margin:0}.sheetbody{overflow:auto;padding:14px}.group{border:0;margin:0 0 12px;padding:0}.group legend{font-size:14px;font-weight:750;margin:0 0 4px}.sheet input[type=number],.sheet select{font:inherit;width:100%;padding:7px;border:1px solid #b6c5b9;border-radius:8px;color:var(--ink);background:#fff}.sheet label{font-size:13px}.notice{white-space:pre-line;color:#733b17;font-size:13px}.loader{font-size:12px;color:var(--muted)}
@media(max-width:520px){.panel{bottom:0;right:0;width:100vw;height:min(760px,100dvh);border-radius:18px 18px 0 0;border-bottom:0}.panel header{padding-top:max(13px,env(safe-area-inset-top))}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}`;
